mapper.select:
select articleImgUrl
from fitian.ArticleImage
where articleNo = #{articleNo}

mapper.update:
update fitian.Article
SET articleTitle=#{articleTitle}, articleScript=#{articleScript}, category=#{category}
where articleNo = #{articleNo}

mapper.delete:
delete from fitian.Article
where uid = #{uid}
and articleNo = #{articleNo}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM fitian.Article WHERE uid = #{uid} and articleNo = #{articleNo}
) AS exist

mapper.update:
update fitian.ArticleImage
SET articleImgUrl=#{articleImgUrl}
where articleNo = #{articleNo}
